authenticationType.customDisplay:
{{velocity}}
#set ($id = $escapetool.xml("${prefix}${name}"))
{{html clean="false"}}
<select id="$id" name="$id" class="jira-config-authentication-type">
<option value="noAuth" #if ($value == 'noAuth') selected #end>$services.localization.render('jira.config.auth.noAuth')</option>
#foreach ($u in $services.uix.getExtensions('org.xwiki.contrib.jira.authconfig'))
  <option value="$u.parameters.config_id" #if ($value == $u.parameters.config_id) selected #end>$services.localization.render($u.parameters.translation_key)</option>
#end
</select>
{{/html}}
{{/velocity}}
